export type AppIconComponent = FC<IconProps>

export function AppIcon({
  icon: Icon,
  size = 16,
  className,
  ...props
}: IconProps & { icon: AppIconComponent }) {
  return <Icon size={size} className={className} {...defaultIconProps} {...props} />
}

